class Solution {
    public String[] sortPeople(String[] names,int[] heights){
        Integer[] indices=new Integer[names.length];
        for(int i=0;i<names.length;i++)indices[i]=i;
        Arrays.sort(indices,(a,b)->Integer.compare(heights[b],heights[a]));
        String[] answer=new String[names.length];
        for(int i=0;i<names.length;i++)answer[i]=names[indices[i]];
        return answer;
    }
}

code.kotlin:
class Solution {
    fun sortPeople(names:Array<String>,heights:IntArray):Array<String>{
        val indices=names.indices.sortedByDescending{
            heights[it]
        };
        return Array(names.size){
            names[indices[it]]
        }
    }
}

code.cpp:
class Solution {
    public:vector<string> sortPeople(vector<string>& names,vector<int>& heights){
        vector<int> indices(names.size());
        iota(indices.begin(),indices.end(),0);
        sort(indices.begin(),indices.end(),[&](int a,int b){
            return heights[a]>heights[b];
        });
        vector<string> answer;
        for(int index:indices)answer.push_back(names[index]);
        return answer;
    }
};
